-- Fix 07/08/2026 — unita' di misura del gas e prezzi implausibili.
--
-- Il refresh 06/08 leggeva il prezzo energia solo con UNITA_MISURA 03 (euro/kWh).
-- Il gas usa la 04 (euro/Smc): risultato, TUTTI gli spread gas a 0 e nessuna
-- fissa gas in catalogo. Qui: (1) si scadono le fisse elettriche con prezzo
-- sotto 0,09 euro/kWh (PUN 0,115: non sono prezzi pieni ma componenti parziali
-- finite nel campo sbagliato — scadute e non cancellate per non violare la FK
-- di en.proposals); (2) si correggono le gas esistenti per codice offerta;
-- (3) si scadono le gas fisse sotto 0,35 euro/Smc (PSV 0,48); (4) si
-- inseriscono le gas mancanti (le fisse prima escluse). Idempotente.

begin;

update en.offers set validity_end = current_date - 1, updated_at = now()
 where commodity='ele' and price_type='fixed'
   and coalesce(price_f0, price_f1) < 0.09
   and (validity_end is null or validity_end >= current_date);

update en.offers o set
    spread_eur = v.spread_eur::numeric,
    price_f0 = v.price_f0::numeric, price_f1 = v.price_f1::numeric,
    price_f2 = v.price_f2::numeric, price_f3 = v.price_f3::numeric,
    fixed_fee_year = coalesce(v.fixed_fee_year::numeric, 0),
    updated_at = now()
